        html: `<p>Найчастіші проблеми: некоректний підбір КВЕД, нечіткий розподіл часток між партнерами, ігнорування правил оподаткування на старті та формальний статут, що не враховує реальних домовленостей. Кожна з цих помилок може коштувати часу й грошей, а інколи — і конфлікту між засновниками. Наприклад, відсутність у статуті основного для діяльності КВЕД інколи блокує роботу з окремими контрагентами або участь у тендерах, а помилковий розподіл часток 50/50 без механізму виходу з тупикової ситуації здатний паралізувати ухвалення рішень.</p>
<p>Ще одна типова прогалина — невизначеність меж повноважень директора. Якщо статут не встановлює суми правочинів, які потребують згоди загальних зборів, керівник фактично отримує необмежений мандат, і учасники втрачають контроль над значними угодами. Так само ризиковано залишати без уваги порядок успадкування частки: за відсутності чітких правил спадкоємці учасника можуть несподівано стати співвласниками бізнесу.</p>
<p>Ще одна поширена помилка — нехтування захистом компанії від недружніх дій уже на старті; як цьому запобігти, ми пояснюємо у статті про <a href="/blog/zakhyst-vid-reyderstva/">захист від рейдерства</a>. Щоб уникнути ризиків, реєстрацію варто планувати разом із податковою стратегією — про неї читайте в розділі <a href="/practices/tax-law/">податкове право</a>. Команда LEGIUS супроводжує реєстрацію «під ключ» і відповідає за результат.</p>`,
