<p>Мета ліцензування — забезпечити, щоб певні види діяльності здійснювали лише суб’єкти, які відповідають установленим вимогам до кваліфікації, матеріальної бази та організації роботи. Тому ліцензія — це не формальність, а підтвердження готовності працювати в регульованій сфері.</p>
