        html: `<p>Холдингова структура — це група компаній, об’єднаних відносинами контролю, де материнська компанія володіє частками в дочірніх. Така модель дозволяє відокремити володіння активами від операційної діяльності та гнучко керувати групою, розподіляючи ризики й функції між окремими юридичними особами.</p>
<p>Холдинги застосовують і малий, і великий бізнес: від розділення двох напрямів діяльності до побудови розгалужених міжнародних груп. Головне — щоб структура відповідала реальним бізнес-цілям, а не існувала формально.</p>
<p>Побудова холдингу тісно пов’язана з угодами M&A — детальніше в розділі <a href="/practices/m-and-a/">M&amp;A</a>. Огляд тем — у хабі <a href="/blog/korporatyvne-pravo/">Корпоративне право</a>.</p>`,
