        h2: "Українське право і GDPR",
        html: `<p>Захист персональних даних в Україні регулюється профільним законом, а для бізнесу, що працює з резидентами ЄС, додатково діє Загальний регламент захисту даних (GDPR). Ці режими мають спільну логіку, але різні вимоги та рівень санкцій, тому їх не можна ототожнювати.</p>
<p>Для компаній, орієнтованих на міжнародний ринок, дотримання GDPR — не лише вимога закону, а й питання довіри клієнтів і партнерів. Невідповідність може закрити доступ до європейського ринку.</p>
<p>Захист даних тісно пов’язаний із <a href="/blog/zakhyst-komertsiynoyi-tayemnytsi/">комерційною таємницею</a> та <a href="/blog/kep-elektronnyy-dokumentoobih/">електронним документообігом</a>. Огляд тем — у хабі <a href="/blog/korporatyvne-pravo/">Корпоративне право</a>.</p>`,
