<li><b>Періодичне підтвердження</b> — навіть якщо нічого не змінилося, відомості потрібно підтверджувати. Порядок і строки цієї процедури під час воєнного стану неодноразово коригувалися, тому їх варто звіряти з чинною редакцією перед поданням.</li>
