        h2: "Що вирішують збори",
        html: `<p>Загальні збори — вищий орган ТОВ. Частину питань закон відносить до їх виключної компетенції, і директор не може вирішити їх самостійно, навіть якщо статут сформульовано широко.</p>
<p>До компетенції зборів належать, зокрема: внесення <a href="/blog/zminy-do-statutu-tov/">змін до статуту</a>, <a href="/blog/zbilshennya-statutnoho-kapitalu-tov/">зміна розміру статутного капіталу</a>, обрання та припинення повноважень директора, розподіл прибутку й виплата <a href="/blog/dyvidendy-tov/">дивідендів</a>, затвердження результатів діяльності, а також <a href="/blog/likvidatsiya-kompanii/">припинення товариства</a>.</p>
<p>Рішення, ухвалене неналежним органом, є вразливим. Тому перед будь-якою значною дією варто перевірити, хто саме має її ухвалювати за законом і статутом.</p>`,
