        html: `<p>Вимоги про кворум у класичному вигляді для ТОВ скасовано — збори не «не відбуваються» через неявку. Натомість рішення вважається прийнятим, якщо за нього подано потрібну кількість голосів <b>від загальної кількості голосів усіх учасників</b>, а не лише присутніх.</p>
<p>Практично це означає, що учасник з великою часткою може заблокувати рішення простою неявкою — його голоси все одно враховуються в знаменнику.</p>
<p>Більшість питань вирішується простою більшістю голосів усіх учасників. Окремі — зміна статуту, зміна розміру статутного капіталу — потребують кваліфікованої більшості у три чверті голосів. Для деяких питань закон вимагає одностайності.</p>
<p>Точний розподіл варто звіряти зі статутом і законом перед голосуванням: помилка в потрібній кількості голосів робить рішення оспорюваним.</p>`,
