<p><b>Обмеження друге — розподіл.</b> Отриманий дохід не може бути розподілений між засновниками, членами чи керівництвом. Він спрямовується виключно на статутну діяльність. Оплата праці працівників розподілом не вважається, але вона має бути ринковою й оформленою.</p>
