        id: "s1",
        h2: "Що таке громадська спілка",
        html: `<p>Громадська спілка — це одна з двох форм громадського об’єднання, передбачених законом. Від громадської організації вона відрізняється складом засновників: <b>спілку засновують юридичні особи приватного права</b>, а не громадяни.</p>
<p>Це та форма, у якій в Україні найчастіше існують галузеві та професійні об’єднання: асоціації виробників, об’єднання ІТ-компаній, спілки перевізників, професійні спільноти. Коли кілька компаній хочуть діяти спільно — представляти галузь, розробляти стандарти, вести діалог з органами влади — саме громадська спілка є робочим інструментом.</p>
<p>Як і громадська організація, спілка не має на меті одержання прибутку, а її майно не може бути розподілене між засновниками чи членами. Базові правила ті самі, і ми розібрали їх у матеріалі про <a href="/blog/reyestratsiya-gromadskoyi-organizatsiyi/">реєстрацію громадської організації</a>.</p>`,
