<p>Рішення про участь у створенні спілки ухвалює <b>уповноважений орган кожної компанії-засновника</b>. Для ТОВ це, як правило, загальні збори учасників — порядок їх скликання розібраний у матеріалі про <a href="/blog/zahalni-zbory-uchasnykiv-tov/">загальні збори учасників ТОВ</a>.</p>
