        id: "s1",
        h2: "Асоціація — це не форма, а назва",
        html: `<p>Перше, що варто зрозуміти: в українському законодавстві немає організаційно-правової форми під назвою «асоціація» у тому вигляді, у якому це слово вживають у розмові.</p>
<p>«Асоціація виробників», «асоціація перевізників», «професійна асоціація» — це <b>найменування</b>, яке організація бере собі сама. А юридично вона існує в одній із передбачених законом форм, і саме її треба обрати свідомо.</p>
<p>Наслідок практичний: питання «як зареєструвати асоціацію» насправді означає «яку форму обрати під наші цілі». Від відповіді залежить склад засновників, оподаткування, можливість отримувати гранти й межі допустимої діяльності.</p>`,
