        id: "s6",
        h2: "Відмова та її оскарження",
        html: `<p>Відмова має бути <b>письмовою і мотивованою</b>, з посиланням на конкретну норму закону. Відмова «на підставі внутрішнього порядку» або усна відмова юридичної сили не мають.</p>
<p>Законні підстави для відмови обмежені: подання неповного пакета документів, виявлення недостовірних відомостей, невідповідність об’єкта вимогам законодавства.</p>
<p>Порядок дій:</p>
<ol>
<li><b>Отримати відмову письмово.</b> Без неї немає предмета оскарження — і, до речі, немає й підстав для мовчазної згоди.</li>
<li><b>Оцінити мотиви.</b> Якщо недолік усувний, часто швидше усунути й подати повторно.</li>
<li><b>Оскаржити до органу вищого рівня</b> в адміністративному порядку.</li>
<li><b>Звернутися до адміністративного суду</b> — дозвільний орган є суб’єктом владних повноважень.</li>
</ol>
<p>У судових справах цієї категорії найсильніші аргументи — процедурні: порушення строку розгляду, немотивованість відмови, вимога документів, не передбачених законом.</p>`,
